import { readFileSync, readdirSync, writeFileSync } from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TOKENS_DIR = path.resolve(__dirname, "../tokens");
const SCSS_DIR = path.resolve(__dirname, "../../../foundation_cms/static/scss");

const GENERATED_HEADER_BASE = [
  "// Generated by frontend/redesign/tools/build-tokens.js. Do not edit by hand.",
  "// Source: frontend/redesign/tokens/*.json — edit there and re-run `yarn build:tokens`.",
];

const CSS_HEADER = [
  ...GENERATED_HEADER_BASE,
  "// CSS custom properties, for runtime use in component CSS: var(--token-name).",
  "// Needs a real value at compile time instead (a breakpoint, a Foundation",
  "// setting)? Use settings/_tokens.scss, not this file.",
];

const SASS_MAP_HEADER = [
  ...GENERATED_HEADER_BASE,
  "// Sass $tokens map, for anything needing a real value at compile time:",
  '// map.get($tokens, "token-name"). Reading a token at runtime in component',
  "// CSS instead? Use ../_tokens.scss, not this file.",
];

/**
 * Flattens a token JSON object into a single-level map of hyphenated names to
 * raw values. Skips any key starting with "$" ($description, $meta) since
 * those are annotations, not tokens.
 *
 * A node is a leaf token once it has both "value" and "description" keys —
 * anything else is a deeper category to keep recursing into. This matches
 * the shape of the token JSON files LP passed us (see tokens/*.json), which
 * follow the W3C design token format: every leaf is a { value, description }
 * object, and references between tokens use "{dot.path}" braces.
 *
 * Example: { color: { border: { default: { value: "#161616", description: "..." } } } }
 * becomes { "color-border-default": "#161616" }
 */
function flatten(node, prefix, out) {
  for (const [key, value] of Object.entries(node)) {
    if (key.startsWith("$")) continue;

    const nextPrefix = prefix ? `${prefix}-${key}` : key;

    if (value && typeof value === "object" && "value" in value) {
      out[nextPrefix] = value.value;
    } else if (value && typeof value === "object") {
      flatten(value, nextPrefix, out);
    }
  }
  return out;
}

/**
 * Resolves "{dot.path}" references between tokens in place, e.g.
 * "color-border-default": "{color.gray.1000}" becomes "color-border-default": "#161616".
 *
 * The dot.path inside the braces is LP's original naming (matches the JSON
 * structure before flattening), so it gets converted to our hyphenated key
 * format before the lookup. Follows chained references (a token pointing at
 * a token that is itself a reference) and throws on a circular one instead
 * of infinite-looping.
 */
function resolveRefs(tokens) {
  const refPattern = /^\{(.+)\}$/;

  function resolve(value, seen) {
    const match = typeof value === "string" && value.match(refPattern);
    if (!match) return value;

    const refKey = match[1].replace(/\./g, "-");
    if (seen.has(refKey)) {
      throw new Error(
        `Circular token reference: ${[...seen, refKey].join(" -> ")}`,
      );
    }
    if (!(refKey in tokens)) {
      throw new Error(`Unresolved token reference: {${match[1]}}`);
    }

    return resolve(tokens[refKey], new Set(seen).add(refKey));
  }

  for (const key of Object.keys(tokens)) {
    tokens[key] = resolve(tokens[key], new Set());
  }
  return tokens;
}

/**
 * Reads every JSON file in tokens/, flattens and merges them into one map,
 * then resolves every "{dot.path}" reference against the merged set. This
 * is the point where the raw JSON becomes the final, literal token values
 * both output formats (CSS custom properties and the Sass map) get built
 * from.
 */
function loadTokens() {
  const tokens = {};
  const files = readdirSync(TOKENS_DIR).filter((file) =>
    file.endsWith(".json"),
  );

  for (const file of files) {
    const json = JSON.parse(readFileSync(path.join(TOKENS_DIR, file), "utf8"));
    flatten(json, "", tokens);
  }

  return prefixMotionTokens(resolveRefs(tokens));
}

/**
 * Adds an `mzf-` prefix to motion tokens (--mzf-motion-duration-base), because
 * that's the name LP's CSS uses for them. Other token categories stay
 * unprefixed (--space-32). Runs after resolveRefs, because references in the
 * JSON point at the unprefixed names.
 */
function prefixMotionTokens(tokens) {
  const out = {};
  for (const [name, value] of Object.entries(tokens)) {
    out[name.startsWith("motion-") ? `mzf-${name}` : name] = value;
  }
  return out;
}

/**
 * Two outputs, because the tokens have two different consumers that resolve
 * values at two different times.
 *
 * CSS custom properties are resolved by the browser at paint time, so
 * they're fine for anything a component reads directly, like a color or a
 * padding. But Sass itself, and Foundation-Sites' own settings, resolve
 * everything once at compile time, before any CSS exists, so they can't
 * read a custom property. Media query breakpoints are the clearest case:
 * `@media (min-width: var(--x))` isn't valid CSS in any browser, so a
 * breakpoint token has to exist as a real Sass value, not a custom
 * property, for anything that writes a media query with it.
 *
 * So: _tokens.scss (CSS custom properties) for runtime use in our own
 * component CSS, and settings/_tokens.scss (a Sass map) for anything
 * Foundation or our own Sass needs to resolve at compile time.
 */

/**
 * Writes the resolved tokens as CSS custom properties in a :root block, for
 * anything that reads a token at runtime in component CSS, e.g.
 * `color: var(--color-border-default);`.
 */
function writeCssCustomProperties(tokens) {
  const lines = [
    ...CSS_HEADER,
    ":root {",
    ...Object.keys(tokens)
      .sort()
      .map((name) => `  --${name}: ${tokens[name]};`),
    "}",
    "",
  ];

  writeFileSync(path.join(SCSS_DIR, "_tokens.scss"), lines.join("\n"));
}

/**
 * A bare comma-separated value (a font stack like 'Mozilla Text', system-ui,
 * sans-serif) is indistinguishable, to Sass's map parser, from the commas
 * that separate one "key: value" pair from the next. Wrapping it in
 * parentheses turns it into a single list value instead. A value that's
 * already a single function call, like rgba(0, 0, 0, 0.2), doesn't need
 * this (its own parens already scope those commas), but wrapping it anyway
 * is harmless, so this checks for any comma rather than trying to tell the
 * two cases apart.
 */
function sassValue(value) {
  return value.includes(",") ? `(${value})` : value;
}

/**
 * Writes the resolved tokens as a Sass map, for anything that needs a real
 * value at compile time instead of a runtime CSS variable, e.g. a media
 * query breakpoint or a Foundation settings override:
 * `map.get($tokens, "size-breakpoint-mobile")`.
 */
function writeSassMap(tokens) {
  const lines = [
    ...SASS_MAP_HEADER,
    '@use "sass:map";',
    "",
    "$tokens: (",
    ...Object.keys(tokens)
      .sort()
      .map((name) => `  "${name}": ${sassValue(tokens[name])},`),
    ");",
    "",
  ];

  writeFileSync(
    path.join(SCSS_DIR, "settings", "_tokens.scss"),
    lines.join("\n"),
  );
}

const tokens = loadTokens();
writeCssCustomProperties(tokens);
writeSassMap(tokens);
console.log(
  `Wrote ${Object.keys(tokens).length} tokens to _tokens.scss and settings/_tokens.scss.`,
);
